//
//  FormattingTests.swift
//  mdTests
//
//  MarkdownFormatting against the shared oracle — the same file in md and
//  md.macOS.
//
//  FormattingVectors/formatting-vectors.json is the cross-port contract for
//  `format` and `wrapTyped`: 127 + 10 vectors generated by the TypeScript
//  reference md.win's docs/formatting.md was written against, copied
//  verbatim into md, md.macOS, md.Android and md.win — the arrangement
//  typing-vectors.json has for SmartTyping. Every offset is a UTF-16 code
//  unit; `expected` is the JSON literal null for "no edit". No vector is
//  skipped and none is close enough: a disputed one is changed in the
//  reference first, in one commit across the repos.
//

import XCTest
@testable import md

final class FormattingTests: XCTestCase {

    private struct Expected: Decodable, Equatable {
        let start: Int
        let end: Int
        let text: String
        let selectionStart: Int
        let selectionEnd: Int
    }

    private struct Vector: Decodable {
        let id: String
        let op: String?
        let typed: String?
        let text: String
        let selectionStart: Int
        let selectionEnd: Int
        let expected: Expected?
    }

    private struct Vectors: Decodable {
        let version: Int
        let format: [Vector]
        let wrapTyped: [Vector]
    }

    private static let vectors: Vectors = {
        guard let url = Bundle(for: FormattingTests.self)
            .url(forResource: "formatting-vectors", withExtension: "json", subdirectory: "FormattingVectors"),
              let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode(Vectors.self, from: data) else {
            fatalError("missing or unreadable FormattingVectors/formatting-vectors.json")
        }
        return decoded
    }()

    private func actual(_ edit: MarkdownFormatting.Edit?) -> Expected? {
        edit.map { Expected(start: $0.start, end: $0.end, text: $0.text,
                            selectionStart: $0.selectionStart, selectionEnd: $0.selectionEnd) }
    }

    func testTheOracleIsWhole() {
        XCTAssertEqual(Self.vectors.version, 1)
        XCTAssertEqual(Self.vectors.format.count, 127)
        XCTAssertEqual(Self.vectors.wrapTyped.count, 10)
        // Every command is exercised by at least one vector — except
        // `heading5`, which version 1 of the oracle happens to carry none
        // for (heading1…4 and 6 pin the same code path). A vector added for
        // it in the reference should delete this exception.
        let ops = Set(Self.vectors.format.compactMap(\.op))
        XCTAssertEqual(ops, Set(MarkdownFormatting.Op.allCases.map(\.rawValue)).subtracting(["heading5"]))
    }

    func testEveryFormatVector() throws {
        for v in Self.vectors.format {
            let op = try XCTUnwrap(MarkdownFormatting.Op(rawValue: v.op ?? ""), v.id)
            let edit = MarkdownFormatting.format(v.text, selectionStart: v.selectionStart,
                                                 selectionEnd: v.selectionEnd, op: op)
            XCTAssertEqual(actual(edit), v.expected, v.id)
        }
    }

    func testEveryWrapTypedVector() throws {
        for v in Self.vectors.wrapTyped {
            let edit = MarkdownFormatting.wrapTyped(v.text, selectionStart: v.selectionStart,
                                                    selectionEnd: v.selectionEnd, typed: try XCTUnwrap(v.typed))
            XCTAssertEqual(actual(edit), v.expected, v.id)
        }
    }

    /// The selection the vectors give is in the resulting text, so applying
    /// an edit and reading the selection back is the round trip an editor
    /// makes — checked on one case per family of command.
    func testApplyAndSelectionAgree() {
        let text = "say hello now"
        let edit = MarkdownFormatting.format(text, selectionStart: 4, selectionEnd: 9, op: .bold)!
        let result = MarkdownFormatting.apply(edit, to: text)
        XCTAssertEqual(result, "say **hello** now")
        let selected = (result as NSString).substring(with: NSRange(location: edit.selectionStart,
                                                                     length: edit.selectionEnd - edit.selectionStart))
        XCTAssertEqual(selected, "hello")
        // Applying the same command again takes it back off.
        let undo = MarkdownFormatting.format(result, selectionStart: edit.selectionStart,
                                             selectionEnd: edit.selectionEnd, op: .bold)!
        XCTAssertEqual(MarkdownFormatting.apply(undo, to: result), text)
    }
}
